const purgeErasedCallInitiators = `-- name: PurgeErasedCallInitiators :execrows
UPDATE calls SET created_by = NULL WHERE id IN (
 SELECT c.id FROM calls c JOIN users u ON u.id = c.created_by
 WHERE u.auth_service = 'erased' AND NOT call_held(c.id) ORDER BY c.id LIMIT $1
)
`

func (q *Queries) PurgeErasedCallInitiators(ctx context.Context, rowLimit int32) (int64, error) {
	result, err := q.db.Exec(ctx, purgeErasedCallInitiators, rowLimit)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const purgeExpiredCalls = `-- name: PurgeExpiredCalls :execrows
DELETE FROM calls WHERE id IN (
 SELECT c.id FROM calls c JOIN channels ch ON ch.id = c.channel_id
 JOIN workspaces w ON w.id = ch.workspace_id
 WHERE c.ended_at IS NOT NULL AND coalesce(ch.retention_days, w.retention_days) IS NOT NULL
  AND c.ended_at < now() - make_interval(days => coalesce(ch.retention_days, w.retention_days))
  AND NOT call_held(c.id)
 ORDER BY c.id LIMIT $1
)
`

func (q *Queries) PurgeExpiredCalls(ctx context.Context, rowLimit int32) (int64, error) {
	result, err := q.db.Exec(ctx, purgeExpiredCalls, rowLimit)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

