const userCallMetadataAfter = `-- name: UserCallMetadataAfter :many
SELECT c.id AS call_id, c.channel_id, c.state, c.created_at, c.started_at, c.ended_at, c.end_reason,
 p.id AS participant_id, p.state AS participant_state, p.joined_at, p.left_at
FROM calls c JOIN call_participants p ON p.call_id = c.id
WHERE p.user_id = $1 AND p.redacted_at IS NULL
 AND ($2::uuid IS NULL OR p.id > $2::uuid)
ORDER BY p.id LIMIT $3
`

type UserCallMetadataAfterParams struct {
	UserID   pgtype.UUID `json:"user_id"`
	After    pgtype.UUID `json:"after"`
	RowLimit int32       `json:"row_limit"`
}

type UserCallMetadataAfterRow struct {
	CallID           pgtype.UUID        `json:"call_id"`
	ChannelID        pgtype.UUID        `json:"channel_id"`
	State            string             `json:"state"`
	CreatedAt        time.Time          `json:"created_at"`
	StartedAt        pgtype.Timestamptz `json:"started_at"`
	EndedAt          pgtype.Timestamptz `json:"ended_at"`
	EndReason        string             `json:"end_reason"`
	ParticipantID    pgtype.UUID        `json:"participant_id"`
	ParticipantState string             `json:"participant_state"`
	JoinedAt         pgtype.Timestamptz `json:"joined_at"`
	LeftAt           pgtype.Timestamptz `json:"left_at"`
}

func (q *Queries) UserCallMetadataAfter(ctx context.Context, arg UserCallMetadataAfterParams) ([]UserCallMetadataAfterRow, error) {
	rows, err := q.db.Query(ctx, userCallMetadataAfter, arg.UserID, arg.After, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UserCallMetadataAfterRow
	for rows.Next() {
		var i UserCallMetadataAfterRow
		if err := rows.Scan(
			&i.CallID,
			&i.ChannelID,
			&i.State,
			&i.CreatedAt,
			&i.StartedAt,
			&i.EndedAt,
			&i.EndReason,
			&i.ParticipantID,
			&i.ParticipantState,
			&i.JoinedAt,
			&i.LeftAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
